head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.spacYN = "N";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.pMenuID = $c.cm.InfoMenuID();
scwin.getPar, scwin.setPar;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        if (js_market === '2') {
            // 코스탁
            panel_1.hide();
            panel_2.show("");
            await scwin.delistCode();
        } else {
            // 유가,코넥스

            panel_1.show("");
            panel_2.hide();
        }

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안

        buttonSet.setInsertStatus();
        if (js_market === "6") {
            strCodeCnt = "코스닥시장상장규정 제38조 및 제33조^코스닥시장상장규정 제38조 및 제33조,직접 입력하세요^수기 입력";
        } else {
            strCodeCnt = "코스닥시장상장규정 제23조 및 제54조^코스닥시장상장규정 제23조 및 제54조,코스닥시장상장규정 제23조 및 제82조^코스닥시장상장규정 제23조 및 제82조,직접 입력하세요^수기 입력";
        }
        cmb_GRND_REGUL_NM.CBData = strCodeCnt;
        cmb_GRND_REGUL_NM_2.CBData = strCodeCnt;
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05233.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// function fn_makt() { }

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("회사명을 선택하세요");
        } else {
            scwin.initItem();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05233.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05233.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsur;
        scwin.setPar = scwin.setParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "STF05233") {
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        } else if (scwin.pMenuID === "STF05266") {
            // 기업인수목적 회사
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
            scwin.spacYN = "Y";
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }

        // fn_PopFindCorpChrg(fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05233.img_COM_NM_onclick" });
    }
};

