 */
scwin.cmb_GRND_REGUL_NM_onselchange = function() {
    try {
        txb_GRND_REGUL_NM.setValue(cmb_GRND_REGUL_NM.getValue());
        if (txb_GRND_REGUL_NM.getValue() === "직접 입력하세요") {
