/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            if ($c.ut.cGetToday("yyyymmdd") <= edt_DELIST_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                // alert('[DISCLS_YN]'+dts_Mst.NameValue(1, "DISCLS_YN"));
                $c.stf.setButtonSetWithDate2(dts_Mst.getCellData(1, "DISCLS_YN"));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05233.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount === 0) {
            const sbmOptions = {
                id : "sbm_dts_Mst",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Mst=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Mst.insertRow();
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05233.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
        if (dts_List.getRowCount() > 0) {
            await scwin.openDetail(0);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05233.trs_Save_OnSuccess" });
    }
};

