        txb_DELIST_RSN.setValue(cmb_DELIST_RSN_DSC.getValue());
        if (txb_DELIST_RSN.getValue() === '직접 입력하세요') {
            txb_DELIST_RSN.style.backgroundColor = '#ffffff';
            txb_DELIST_RSN.setReadOnly(false);
        } else {
