///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name delistCode
 * @description 코스탁 상장폐지사유 선택
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delistCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_DelistCode",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DelistCode=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "";
    for (let i = 1; i <= dts_DelistCode.getRowCount(); i++) {
        if (dts_DelistCode.getCellData(i, "CODE").substr(0, 1) === "8" && dts_DelistCode.getCellData(i, "CODE").substr(2, 5) !== "0000") {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_DelistCode.getCellData(i, "NAME") + "^" + dts_DelistCode.getCellData(i, "NAME");
        }
    }
    strCbd = strCbd + ",직접 입력하세요^수기입력";
    cmb_DELIST_RSN_DSC.CBData = strCbd;
};

/**
 * @method
 * @name isuReadSync
 * @description isu Read Sync 처리
 * @param {String} vIsuStr vIsuStr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuReadSync = async function(vIsuStr) {
    url += "?SCREN_ID=" + "ULDSTF05233.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=popsearch&inputMessageId=DELISTING_ISU_INOUT&ISU_CD_LIST=" + vIsuStr;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05233.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarketDetail&inputMessageId=DELISTING_INOUT&ISUR_CD=" + txb_ISUR_CD.getValue() + "&MKTACT_APPL_OBJ_TP_CD=1";
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Delisting.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    url += "?SCREN_ID=" + "ULDSTF05233.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=masterDetail&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "?SCREN_ID=" + "ULDSTF05233.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarket&inputMessageId=DELISTING_ISU_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions2 = {
        id : "sbm_dts_Isu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* 2009.06.08 영문공시관련 추가 */
    url += "?SCREN_ID=" + "ULDSTF05233.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=masterDetailEng&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions3 = {
        id : "sbm_dts_Mst_Eng",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Mst_Eng=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

