                // 유가
                txb_DELIST_RSN_DSC.setReadOnly(true);
                txb_DELIST_RSN_DSC.style.backgroundColor = '#b9d4f7';
            } else {
                // 코스탁
                txb_DELIST_RSN.setReadOnly(false);
                txb_DELIST_RSN.style.backgroundColor = '#ffffff';
