 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsu = async function(arrPar) {
    /* 1건 이상의 종목이 선택된 경우를 감안하여 array에 포함된 모든 row를 현재 데이터셋의 SELECT에 반영한다. */
    let vIsuStr = "";
    for (i = 0; i < arrPar.length; i++) {
        if (i === 0) {
            vIsuStr = arrPar[i].ISU_CD;
        } else {
            vIsuStr = vIsuStr + "," + arrPar[i].ISU_CD;
        }
        const vSTKCERT_KIND_CD = arrPar[i].ISU_CD.substring(8, 11);
        if (vSTKCERT_KIND_CD === "000" || vSTKCERT_KIND_CD === "KDR") {
            await $c.win.alert("보통주는 선택할수 없습니다.");
            return;
        }
    }
    await scwin.isuReadSync(vIsuStr);
};

