    if (!await scwin.checkBiz()) {
        return;
    }
    let OldGet = scwin.getPar;
    scwin.getPar = function(arr) {
        arr[0] = scwin.vBzProcsNo;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.getPar = OldGet;
};
